package com.daeyaltminingtimer;

import java.awt.Color;

import net.runelite.api.SoundEffectID;
import net.runelite.client.config.*;

@ConfigGroup(DaeyaltMiningTimerConfig.group)
public interface DaeyaltMiningTimerConfig extends Config
{
	String group = "daeyalt-mining-timer";

	enum TimerStyle
	{
		PIE,
		COUNTDOWN,
		PIE_AND_COUNTDOWN;

		@Override
		public String toString()
		{
			switch (this)
			{
				case PIE:
					return "Pie";
				case COUNTDOWN:
					return "Countdown";
				default:
					return "Pie + countdown";
			}
		}
	}

	enum TimerUnit
	{
		SECONDS,
		TICKS;

		@Override
		public String toString()
		{
			return this == SECONDS ? "Seconds" : "Ticks";
		}
	}

	@ConfigSection(
			name = "Notifications",
			description = "Configure notifications",
			position = 0
	)
	String notificationsSection = "notificationsSection";

	@ConfigItem(
			keyName = "notifications",
			name = "Client notification",
			description = "Trigger a client notification when the daeyalt essence moves",
			section = notificationsSection,
			position = 0
	)
	default Notification notification()
	{
		return Notification.ON;
	}

	@ConfigItem(
			keyName = "ingameSound",
			name = "In-game sound",
			description = "Play an in-game sound when the daeyalt essence moves",
			section = notificationsSection,
			position = 1
	)
	default boolean ingameSound()
	{
		return false;
	}

	@ConfigItem(
			keyName = "soundId",
			name = "Sound ID",
			description = "The in-game sound to play.\n3925 is the Grand Exchange offer chime; other easily-heard options are 2266 (UI beep), 3929 (plop) and 1930 (teleport woosh).",
			section = notificationsSection,
			position = 2
	)
	default int soundId()
	{
		return SoundEffectID.GE_ADD_OFFER_DINGALING;
	}

	@ConfigItem(
			keyName = "soundFollowGameVolume",
			name = "Follow game volume",
			description = "Use the in-game sound effect volume. If muted in-game, it will use the \"Volume\" setting.",
			section = notificationsSection,
			position = 3
	)
	default boolean soundFollowGameVolume()
	{
		return true;
	}

	@ConfigItem(
			keyName = "soundVolume",
			name = "Volume",
			description = "Volume to play the sound effect at when not using game volume.",
			section = notificationsSection,
			position = 4
	)
	@Range(
			min = 1,
			max = 127
	)
	default int soundVolume()
	{
		return 127;
	}

	@ConfigSection(
			name = "Overlays",
			description = "Configure overlays",
			position = 1
	)
	String overlaysSection = "overlaysSection";

	@ConfigItem(
			keyName = "showDaeyaltEssenceIndicator",
			name = "Show indicator",
			description = "Display a mining icon above the daeyalt essence that is ready to be mined",
			section = overlaysSection,
			position = 0
	)
	default boolean showDaeyaltEssenceIndicator()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showDaeyaltEssenceClickbox",
			name = "Show click box",
			description = "Display a click box on the daeyalt essence that is ready to be mined",
			section = overlaysSection,
			position = 1
	)
	default boolean showDaeyaltEssenceClickbox()
	{
		return true;
	}

	@ConfigItem(
			keyName = "showDaeyaltEssenceClickboxAvailable",
			name = "Click box colour",
			description = "Colour of the click box (ignored while mining-state colours are on)",
			section = overlaysSection,
			position = 2
	)
	default Color showDaeyaltEssenceClickboxAvailable()
	{
		return Color.GREEN;
	}

	@ConfigSection(
			name = "Timer",
			description = "Configure the despawn timer",
			position = 2
	)
	String timerSection = "timerSection";

	@ConfigItem(
			keyName = "showDaeyaltEssenceTimer",
			name = "Show timer",
			description = "Display a timer for when the daeyalt essence is about to move",
			section = timerSection,
			position = 0
	)
	default boolean showDaeyaltEssenceTimer()
	{
		return true;
	}

	@ConfigItem(
			keyName = "timerStyle",
			name = "Timer style",
			description = "Pie: shrinking circle. Countdown: a number counting down. Pie + countdown: the number drawn on the circle.",
			section = timerSection,
			position = 1
	)
	default TimerStyle timerStyle()
	{
		return TimerStyle.PIE_AND_COUNTDOWN;
	}

	@ConfigItem(
			keyName = "timerUnit",
			name = "Countdown unit",
			description = "Count down in seconds or game ticks",
			section = timerSection,
			position = 2
	)
	default TimerUnit timerUnit()
	{
		return TimerUnit.SECONDS;
	}

	@ConfigItem(
			keyName = "timerSize",
			name = "Timer size",
			description = "Diameter of the timer circle in pixels",
			section = timerSection,
			position = 3
	)
	@Range(
			min = 10,
			max = 150
	)
	default int timerSize()
	{
		return 25;
	}

	@ConfigItem(
			keyName = "countdownTextSize",
			name = "Countdown text size",
			description = "Font size of the countdown number",
			section = timerSection,
			position = 4
	)
	@Range(
			min = 8,
			max = 72
	)
	default int countdownTextSize()
	{
		return 16;
	}

	@ConfigItem(
			keyName = "timerColour",
			name = "Timer colour",
			description = "Colour of the timer before the essence can move (used while mining-state colours are off)",
			section = timerSection,
			position = 5
	)
	default Color timerColour()
	{
		return new Color(0, 255, 0);
	}

	@ConfigItem(
			keyName = "warningColour",
			name = "Can move colour",
			description = "Colour of the timer once the essence can move at any moment",
			section = timerSection,
			position = 6
	)
	default Color warningColour()
	{
		return new Color(233, 213, 2);
	}

	@ConfigItem(
			keyName = "countdownTextColour",
			name = "Countdown text colour",
			description = "Colour of the countdown number when drawn on the circle",
			section = timerSection,
			position = 7
	)
	default Color countdownTextColour()
	{
		return Color.WHITE;
	}

	@ConfigSection(
			name = "Mining-state colours",
			description = "Change colours depending on whether you are mining the essence",
			position = 3
	)
	String miningSection = "miningSection";

	@ConfigItem(
			keyName = "miningStateColours",
			name = "Enable",
			description = "Colour the timer and click box by whether you are currently mining the essence",
			section = miningSection,
			position = 0
	)
	default boolean miningStateColours()
	{
		return false;
	}

	@ConfigItem(
			keyName = "miningColour",
			name = "Mining colour",
			description = "Colour while you are mining the essence",
			section = miningSection,
			position = 1
	)
	default Color miningColour()
	{
		return new Color(0, 255, 0);
	}

	@ConfigItem(
			keyName = "notMiningColour",
			name = "Not mining colour",
			description = "Colour while you are not mining the essence",
			section = miningSection,
			position = 2
	)
	default Color notMiningColour()
	{
		return new Color(255, 0, 0);
	}

	@ConfigItem(
			keyName = "miningStateOverridesWarning",
			name = "Override can move colour",
			description = "Keep using the mining/not mining colour after the essence can move, instead of the can move colour",
			section = miningSection,
			position = 3
	)
	default boolean miningStateOverridesWarning()
	{
		return false;
	}
}

package com.daeyaltminingtimer;

import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.Constants;
import net.runelite.api.Skill;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.components.ProgressPieComponent;
import net.runelite.client.util.ColorUtil;

import java.awt.*;

public class DaeyaltMiningTimerOverlay extends Overlay {
    private static final int Z_OFFSET = 200;

    private static final int MIN_DESPAWN_TICK = 92;
    private static final int MAX_DESPAWN_TICK = 110;

    private final Client client;
    private final DaeyaltMiningTimerPlugin plugin;
    private final DaeyaltMiningTimerConfig config;
    private final SkillIconManager skillIconManager;

    private Font countdownFont;
    private int countdownFontSize = -1;

    @Inject
    private DaeyaltMiningTimerOverlay(Client client, DaeyaltMiningTimerPlugin plugin, DaeyaltMiningTimerConfig config, SkillIconManager skillIconManager)
    {
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        this.skillIconManager = skillIconManager;

        setLayer(OverlayLayer.ABOVE_SCENE);
        setPosition(OverlayPosition.DYNAMIC);
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (plugin.outsideDaeyaltEssenceMine())
            return null;

        var activeDaeyaltEssence = plugin.getActiveDaeyaltEssence();
        if (activeDaeyaltEssence == null)
            return null;

        var miningStateColours = config.miningStateColours();

        if (config.showDaeyaltEssenceClickbox())
        {
            var clickbox = activeDaeyaltEssence.getClickbox();
            var mousePosition = client.getMouseCanvasPosition();
            if (miningStateColours)
            {
                var border = plugin.getMiningStateColour();
                OverlayUtil.renderHoverableArea(graphics, clickbox, mousePosition, ColorUtil.colorWithAlpha(border, 50), border, border.darker());
            }
            else
            {
                OverlayUtil.renderHoverableArea(graphics, clickbox, mousePosition, plugin.getClickboxFillColorMinable(), plugin.getClickboxBorderColorMinable(), plugin.getClickboxBorderHoverColorMinable());
            }
        }

        if (config.showDaeyaltEssenceIndicator())
        {
            var gameObjectLocation = activeDaeyaltEssence.getLocalLocation();
            OverlayUtil.renderImageLocation(client, graphics, gameObjectLocation, skillIconManager.getSkillImage(Skill.MINING, false), Z_OFFSET);
        }

        if (config.showDaeyaltEssenceTimer())
        {
            var position = activeDaeyaltEssence.getCanvasLocation(0);
            if (position == null)
                return null;

            var spawnedTicks = client.getTickCount() - plugin.getActiveDaeyaltEssenceSpawnTick();
            var canMove = spawnedTicks >= MIN_DESPAWN_TICK;

            Color colour;
            if (miningStateColours && (!canMove || config.miningStateOverridesWarning()))
                colour = plugin.getMiningStateColour();
            else
                colour = canMove ? config.warningColour() : config.timerColour();

            var style = config.timerStyle();

            if (style != DaeyaltMiningTimerConfig.TimerStyle.COUNTDOWN)
            {
                var pie = new ProgressPieComponent();
                pie.setPosition(position);
                pie.setDiameter(config.timerSize());
                pie.setProgress(Math.max(0d, 1.0d - spawnedTicks / (double)MAX_DESPAWN_TICK));
                pie.setBorderColor(colour.darker());
                pie.setFill(colour);
                pie.render(graphics);
            }

            if (style != DaeyaltMiningTimerConfig.TimerStyle.PIE)
            {
                // Count down to the earliest possible move, then to the latest once it can move.
                var remainingTicks = Math.max(0, (canMove ? MAX_DESPAWN_TICK : MIN_DESPAWN_TICK) - spawnedTicks);
                var text = formatCountdown(remainingTicks);
                var textColour = style == DaeyaltMiningTimerConfig.TimerStyle.COUNTDOWN ? colour : config.countdownTextColour();
                renderCentredText(graphics, text, position, textColour);
            }
        }

        return null;
    }

    private String formatCountdown(int ticks)
    {
        if (config.timerUnit() == DaeyaltMiningTimerConfig.TimerUnit.TICKS)
            return Integer.toString(ticks);

        return String.format("%.1f", ticks * Constants.GAME_TICK_LENGTH / 1000.0);
    }

    private void renderCentredText(Graphics2D graphics, String text, net.runelite.api.Point centre, Color colour)
    {
        var size = config.countdownTextSize();
        if (countdownFont == null || countdownFontSize != size)
        {
            countdownFont = FontManager.getRunescapeBoldFont().deriveFont((float) size);
            countdownFontSize = size;
        }

        graphics.setFont(countdownFont);
        var metrics = graphics.getFontMetrics();
        var x = centre.getX() - metrics.stringWidth(text) / 2;
        var y = centre.getY() + (metrics.getAscent() - metrics.getDescent()) / 2;

        OverlayUtil.renderTextLocation(graphics, new net.runelite.api.Point(x, y), text, colour);
    }
}

package com.daeyaltminingtimer;

import com.google.inject.Provides;
import java.awt.Color;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.GameState;
import net.runelite.api.coords.WorldArea;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.events.GameObjectDespawned;
import net.runelite.api.events.GameObjectSpawned;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.Notifier;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.util.ColorUtil;

@Slf4j
@PluginDescriptor(
	name = "Daeyalt Mining Timer",
	description = "Daeyalt essence timers with a countdown, mining-state colours and a resizable timer",
	tags = {"daeyalt", "essence", "mine", "timer", "countdown"}
)
public class DaeyaltMiningTimerPlugin extends Plugin
{
	private static final int DAEYALT_ESSENCE_MINE_REGION_ID = 14744;

	@Inject
	private Client client;

	@Inject
	private DaeyaltMiningTimerConfig config;

	@Inject
	private Notifier notifier;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private DaeyaltMiningTimerOverlay mine;

	@Getter
	private GameObject activeDaeyaltEssence;
	@Getter
	private int activeDaeyaltEssenceSpawnTick = -1;

	@Getter
	private Color clickboxBorderColorMinable;
	@Getter
	private Color clickboxFillColorMinable;
	@Getter
	private Color clickboxBorderHoverColorMinable;

	private boolean inDaeyaltEssenceMine = false;

	// Mining animations loop with short gaps between swings; treat the player as
	// still mining for this many ticks after the last animated tick.
	private static final int MINING_GRACE_TICKS = 2;
	private static final int MINING_DISTANCE = 2;

	@Getter
	private boolean mining;
	private int lastMiningTick = -1;

	@Override
	protected void startUp() throws Exception
	{
		overlayManager.add(mine);

		updateConfig();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (event.getGroup().equals(DaeyaltMiningTimerConfig.group))
			updateConfig();
	}

	private void updateConfig()
	{
		clickboxBorderColorMinable = config.showDaeyaltEssenceClickboxAvailable();
		clickboxFillColorMinable = ColorUtil.colorWithAlpha(clickboxBorderColorMinable, 50);
		clickboxBorderHoverColorMinable = clickboxBorderColorMinable.darker();
	}

	Color getMiningStateColour()
	{
		return mining ? config.miningColour() : config.notMiningColour();
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(mine);

		activeDaeyaltEssence = null;
		activeDaeyaltEssenceSpawnTick = -1;
		mining = false;
		lastMiningTick = -1;

		clickboxFillColorMinable = null;
		clickboxBorderColorMinable = null;
		clickboxBorderHoverColorMinable = null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		var gameState = event.getGameState();
		if (gameState != GameState.LOADING)
			return;

		activeDaeyaltEssence = null;
		activeDaeyaltEssenceSpawnTick = -1;
	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned event)
	{
		var obj = event.getGameObject();

		switch (obj.getId())
		{
			case ObjectID.DAEYALT_STONE_TOP_ACTIVE:
				if (obj == activeDaeyaltEssence)
					return;

				if (activeDaeyaltEssenceSpawnTick > 0)
				{
					notifier.notify(config.notification(), "Daeyalt Essence Mine spawned");

					if (config.ingameSound())
					{
						var volume = config.soundVolume();

						if (config.soundFollowGameVolume())
						{
							client.playSoundEffect(config.soundId(), volume);
						}
						else
						{
							var prefs = client.getPreferences();
							var prev = prefs.getSoundEffectVolume();
							prefs.setSoundEffectVolume(volume);
							client.playSoundEffect(config.soundId(), volume);
							prefs.setSoundEffectVolume(prev);
						}
					}
				}

				activeDaeyaltEssenceSpawnTick = client.getTickCount();
				activeDaeyaltEssence = obj;
				break;
			case ObjectID.DAEYALT_STONE_TOP:

				break;
		}
	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned event)
	{
		var object = event.getGameObject();
		if (object.getId() == ObjectID.DAEYALT_STONE_TOP_ACTIVE && object == activeDaeyaltEssence)
			activeDaeyaltEssence = null;
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		var player = client.getLocalPlayer();
		if (player == null)
		{
			inDaeyaltEssenceMine = false;
			return;
		}

		var worldLocation = player.getWorldLocation();
		if (worldLocation == null)
		{
			inDaeyaltEssenceMine = false;
			return;
		}

		var region = worldLocation.getRegionID();
		inDaeyaltEssenceMine = region == DAEYALT_ESSENCE_MINE_REGION_ID;

		if (!inDaeyaltEssenceMine)
		{
			activeDaeyaltEssence = null;
			activeDaeyaltEssenceSpawnTick = -1;
			mining = false;
			return;
		}

		var tick = client.getTickCount();
		if (player.getAnimation() != -1 && nearActiveDaeyaltEssence(worldLocation))
			lastMiningTick = tick;
		mining = activeDaeyaltEssence != null && lastMiningTick >= 0 && tick - lastMiningTick <= MINING_GRACE_TICKS;
	}

	private boolean nearActiveDaeyaltEssence(WorldPoint playerLocation)
	{
		var obj = activeDaeyaltEssence;
		if (obj == null)
			return false;

		var min = obj.getSceneMinLocation();
		var max = obj.getSceneMaxLocation();
		var sw = WorldPoint.fromScene(obj.getWorldView(), min.getX(), min.getY(), obj.getPlane());
		var area = new WorldArea(sw, max.getX() - min.getX() + 1, max.getY() - min.getY() + 1);
		return area.distanceTo(playerLocation) <= MINING_DISTANCE;
	}

	@Provides
	DaeyaltMiningTimerConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(DaeyaltMiningTimerConfig.class);
	}

	public boolean outsideDaeyaltEssenceMine()
	{
		return !inDaeyaltEssenceMine;
	}
}

package com.daeyaltminingtimer;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class DaeyaltMiningTimerTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(DaeyaltMiningTimerPlugin.class);
		RuneLite.main(args);
	}
}
